steps.run:
R="$(cd "$VERIFY_WORKDIR/../../../.." && pwd)"
find_output() {  # job id, file name, sha256: the collected output, wherever the runner kept it
  for f in "$R/lib/target/$2" "$R/verification/results/$1/outputs/lib/target/$2"; do
    if [ -f "$f" ] && printf '%s  %s\n' "$3" "$f" | sha256sum -c --quiet - >/dev/null 2>&1; then echo "$f"; return 0; fi
  done
  return 1
}
OLD=$(find_output 20261107-183544-vf-010-s-benchmark-at-the-fix-s-parent-r benchmark-native-vf010-parent.json ad9d1ad88ea06db3558f49e650a1953a6f5650ef86102e70a8616d18095732a6) || { echo "the parent run's collected output is missing or not the one it recorded"; exit 2; }
NEW=$(find_output 20261107-183538-vf-010-s-benchmark-at-the-fix-run-1-of-2 benchmark-native-vf010-fix.json 8309386efe24f80242bae8944ad1de690d56c4188de4526038fbd33590a71d4b) || { echo "the fix run's collected output is missing or not the one it recorded"; exit 2; }
echo "at the fix's parent (c307e721): $OLD"
echo "at the fix (f606b0d8): $NEW"
OLD="$OLD" NEW="$NEW" python3 - <<'PY'
import json, os, sys
new = [r for r in json.load(open(os.environ["NEW"]))["runs"] if r["engine"] == "native"]
old = {(r["case"], r["mode"]): r for r in json.load(open(os.environ["OLD"]))["runs"] if r["engine"] == "native"}
changed, grown, merged, fresh = [], [], [], []
seen = set()
for r in new:
    k = (r["case"], r["mode"]); seen.add(k)
    o = old.get(k)
    if o is None:
        fresh.append((r["case"], r["mode"], r["verdict"]))
        continue
    if r["verdict"] != o["verdict"]:
        changed.append((r["case"], r["mode"], o["verdict"], r["verdict"]))
    s, t = (o.get("solver") or {}), (r.get("solver") or {})
    if s.get("clauses") and t.get("clauses") and t["clauses"] > 1.10 * s["clauses"]:
        grown.append((r["case"], r["mode"], s["clauses"], t["clauses"]))
    if t.get("merges", 0) != s.get("merges", 0) or t.get("paths") != s.get("paths"):
        merged.append((r["case"], r["mode"], s.get("paths"), t.get("paths"), s.get("merges"), t.get("merges"), s.get("clauses"), t.get("clauses")))
gone = sorted(k for k in old if k not in seen)
print(f"own-checker runs: {len(new)}; new cases: {len(fresh)}; cases gone: {len(gone)}; verdicts changed: {len(changed)}; formulas grown past 10%: {len(grown)}; paths or merges changed: {len(merged)}")
for f in fresh: print("  new:", *f)
for g in gone: print("  gone:", *g)
for c in changed: print("  verdict changed:", *c)
for g in grown: print("  clauses grown:", *g)
for m in merged: print("  paths %s->%s merges %s->%s clauses %s->%s:" % m[2:], m[0], m[1])
sys.exit(1 if changed or fresh or gone else 0)
PY

